import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as o,b as n,c as s,d as l,e as r}from"./chunks/Companion6.vBiva1QN.js";import{_ as t,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"App compagno","description":"","frontmatter":{"source_hash":"70c4ce8344","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/install/companion.md","filePath":"it/install/companion.md"}'),m={name:"it/install/companion.md"};function u(h,i,_,g,f,b){return p(),c("div",null,[...i[0]||(i[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Companion App</p></div><p>Se usi l&#39;app del produttore, puoi far sì che xDrip ne ricavi i dati del sensore.</p><p>Questa funzione è disponibile per:</p><ul><li>app G6/G7 (solo master)</li><li>app 1/1+ e Stelo (solo se l&#39;app mostra la glicemia nelle notifiche)</li><li>app CamAPS (compresa la versione canadese)</li><li>app Guardian, MiniMed, Simplera</li><li>app Eversense</li><li>app Micro tech Aidex, LinX Vista, Equil G</li><li>app Micro tech Diaexpert (Germania) e Smart 2 (Brasile)</li><li>app GlucoRx Vixxa (India)</li><li>app Ottai Sens e Tag</li><li>app Pasta</li><li>app CareSens e iCan (Sinocare)</li><li>app Vitatok</li><li>app Glucotech</li><li>app SiSensing Eco (Cina)</li><li>app Diabeloop DBLG2</li></ul><p>Per le app Omnipod 5 e MiniMed Mobile (UE), xDrip legge anche l&#39;insulina attiva (IoB) dalla notifica dell&#39;app compagno, quando disponibile. Per MiniMed Mobile (UE) funziona qualunque sia la lingua dell&#39;app.</p><p>Per usare questa funzione <strong>devi</strong> autorizzare xDrip ad accedere alle notifiche.</p><p>xDrip non userà questo accesso per nessun altro scopo che leggere il valore della glicemia dalle notifiche.</p><div class="admonition xdripitem"><p class="admonition-title">Consentire il permesso</p><p>Il permesso è necessario per ricevere dati da altre applicazioni. xDrip non fa nulla al di là di questo scopo. Abilitare xDrip nella schermata successiva</p><p>     <span style="background-color:white;color:black;"> OK </span></p></div><h4 id="older-android-versions" tabindex="-1">Versioni di Android meno recenti <a class="header-anchor" href="#older-android-versions" aria-label="Permalink to &quot;Versioni di Android meno recenti {#older-android-versions}&quot;">​</a></h4><img src="'+a+'" style="zoom:78%;"><h4 id="android-13-and-above" tabindex="-1">Android 13 e successivi <a class="header-anchor" href="#android-13-and-above" aria-label="Permalink to &quot;Android 13 e successivi {#android-13-and-above}&quot;">​</a></h4><img src="'+o+'" style="zoom:78%;"><img src="'+n+'" style="zoom:78%;"><img src="'+s+'" style="zoom:78%;"><h4 id="allow-notification-access-greyed-out" tabindex="-1">Consenti accesso alle notifiche disattivato (grigio) <a class="header-anchor" href="#allow-notification-access-greyed-out" aria-label="Permalink to &quot;Consenti accesso alle notifiche disattivato (grigio) {#allow-notification-access-greyed-out}&quot;">​</a></h4><img src="'+l+'" style="zoom:78%;"><p>Se non riesci a consentire l&#39;accesso alle notifiche, apri il menu con i tre puntini nelle impostazioni dell&#39;app e scegli Consenti impostazioni con limitazioni (Allow restricted settings).</p><img src="'+r+'" style="zoom:78%;"><br><p>Riceverai i dati in xDrip quando sono disponibili nell&#39;app e le notifiche dell&#39;app sono visibili sul telefono.</p><p>Se non vedi dati e non compare alcun messaggio di errore, potrebbe essere necessario <a href="./../use/startsensor.html#followers-and-companion-apps">Inizializza Sensore</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.20" target="_blank" rel="noreferrer"><em>Ultima modifica 22/11/2026</em></a></p>',23)])])}const q=t(m,[["render",u]]);export{S as __pageData,q as default};
